public static int nullSafeHashCode(long[] array){
    if (array == null){
        return 0;
    }
    int hashCode = 193;
    for (long element : array){
        hashCode = 29 * hashCode + (int)(element ^ (element >>> 32));
    }
    return hashCode;
}

