    if (file == null) {
        throw new NullPointerException("File to delete must not be null");
    }
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        for (File f : files) {
            forceDeleteOnExit(f);
        }
    }
    file.deleteOnExit();
