public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (path == null) {
        return segments;
    }
    int offset = 0;
    int index = 0;
    while (offset < path.length()) {
        // Find the next '/' and add a segment
        int nextSlash = path.indexOf('/', index);
        if (nextSlash == -1) {
            nextSlash = path.length();
        }
        String segment = path.substring(index, nextSlash);
        segments.add(new PathSegmentImpl(segment, decode));
        // Move the index and continue
        index = nextSlash + 1;
        offset = nextSlash + 1;
    }
    return segments;
}

