private InputStream findNextValidStream() throws IOException {
    while (true) {
        if (this.nestedIterator != null && this.nestedIterator.hasNext()) {
            InputStream stream = this.nestedIterator.next();
            if (stream != null) {
                return stream;
            }
        }
        else {
            IOException exception = null;
            try {
                this.nestedIterator = this.nestedIterable.iterator();
            } catch (IOException e) {
                exception = e;
            }
            if (exception != null) {
                throw exception;
            }
        }
    }
}

