public String readString() throws IOException {
    StringBuilder sb = new StringBuilder();
    boolean isEscaping = false;
    boolean closed = false;

    while (!closed) {
        int b = read();
        closed = b == -1;
        if (!closed) {
            if (b == '\\') {
                isEscaping = true;
            } else if (isEscaping) {
                if (b == '"') {
                    sb.append('"');
                } else if (b == 'n') {
                    sb.append('\n');
                } else if (b == 'r') {
                    sb.append('\r');
                } else if (b == 't') {
                    sb.append('\t');
                } else if (b == 'u') {
                    sb.append((char) (Integer.parseInt(readHexNumber()) & 0xFFFF)); // handle Unicode escape sequence
                } else if (b >= '0' && b <= '7') {
                    int octalNumber = b - '0';
                    if (!isEscaping) {
                        octalNumber = readOctalNumber();
                    }
                    sb.append((char) (octalNumber & 0xFFFF));
                } else {
                    sb.append((char) b);
                }
                isEscaping = false;
            } else {
                sb.append((char) b);
            }
        }
    }

    return sb.toString();
}

