     * Refill the buffer if it is empty.
     */
    while (bufferIndex >= bufferSize) {
        bufferIndex = 0;
        bufferSize = inputStream.read(buffer, bufferIndex, buffer.length - bufferIndex);
        if (bufferSize <= 0) {
            break;
        }
    }

    /*
     * Check if there is no more data available.
     */
    if (bufferSize <= 0) {
        throw new IOException("No more data available.");
    }

    /*
     * Read the next byte from the buffer.
     */
    byte result = buffer[bufferIndex];
    bufferIndex++;
    return result;
}

