protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Create a new graph path
    GraphPath<V,E> graphPath = new GraphPath<>(graph);

    // Add the edges in the tour to the graph path
    for (E edge : tour) {
        graphPath.addEdge(edge);
    }

    // Return the graph path
    return graphPath;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize an empty graph path
    GraphPath<V,E> newTour = new GraphPath<V,E>();
    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Get the source and target vertices of the edge
        V source = edge.getSource();
        V target = edge.getTarget();
        // Add the edge to the new tour
        newTour.addEdge(source, target);
        // Add the vertices to the new tour
        newTour.addVertex(source);
        newTour.addVertex(target);
    }
    return newTour;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour.size());
    edgeList.addAll(tour);
    return new GraphPathImpl<V,E>(graph, edgeList);
}

void edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edges = new ArrayList<E>(tour);
    Collections.sort(edges, new EdgeComparator<V,E>(graph));
    List<V> vertices = new ArrayList<V>(edges.size()+1);
    vertices.add(graph.getEdgeSource(edges.get(0)));
    for (E edge : edges) {
        vertices.add(graph.getEdgeTarget(edge));
    }
    return new GraphPathImpl<V,E>(vertices, edges, edges.size());
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    List<E> edges = new ArrayList<>(tour);
    GraphPath<V,E> path = new GraphPath<>(graph);
    for(E edge : edges){
        path.extendWithEdge(edge);
    }
    return path;
}

