    // If the current vertex is null, find the first vertex in the graph.
    if (currentVertex == null) {
        // Use dfs to find the first vertex that has not been used yet.
        dfs.reset();
        Iterator<V> it = dfs.iterator();
        while (it.hasNext()) {
            V vertex = it.next();
            if (!graph.containsVertex(vertex)) {
                currentVertex = vertex;
                break;
            }
        }
    }

    // Return the current vertex.
    V nextVertex = currentVertex;
    currentVertex = null;
    return nextVertex;
}

