private boolean unlink(ListNodeImpl<E> node){
    // If the node is not null and is not the last node in the list
    if (node != null && node.next != null) {
        // Get the previous node
        ListNodeImpl<E> previous = node.previous;
        // Set the previous node's next pointer to the current node's next pointer
        previous.next = node.next;
        // Set the current node's next pointer to the previous node's next pointer
        node.next = previous;
        // Update the current node's previous pointer to the previous node
        node.previous = previous;
        // Decrement the list's size
        size--;
        // Return true to indicate that the node was unlinked
        return true;
    }
    // If the node is null or is the last node in the list
    return false;
}

