public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Initialize variables
    int i = nameStart;
    int count = 0;

    // Iterate over name and check for spaces
    while (i < buf.length() && buf.charAt(i) != ' ') {
        count++;
        i++;
    }

    // If no spaces found, return original name
    if (count == 0) {
        return buf.substring(nameStart);
    }

    // Abbreviate name
    StringBuilder abbr = new StringBuilder();
    for (i = nameStart; i < buf.length(); i++) {
        char c = buf.charAt(i);
        if (c != ' ') {
            abbr.append(c);
        }
    }
    return abbr.toString();
}

