void pop(final String descriptor){
    final StringTokenizer tokenizer = new StringTokenizer(descriptor, "(", true);
    final List<String> tokens = new ArrayList<>();

    while (tokenizer.hasMoreTokens()) {
        tokens.add(tokenizer.nextToken());
    }

    for (int i = 0; i < tokens.size(); i++) {
        final String token = tokens.get(i);

        if (token.equals("(")) {
            break;
        } else if (token.equals(")") || token.equals("(")) {
            continue;
        }

        final AbstractType type = getAbstractType(token);

        if (type != null) {
            pop(type);
        }
    }
}

