public class UriTemplateEncoder {
    private static final Pattern TEMPLATE_NAMES_PATTERN = Pattern.compile("\\{(.+?)\\}");

    /**
     * Encodes a string with template parameters names present, specifically the characters '{' and '}' will be percent-encoded.
     * @param s the string with zero or more template parameters names
     * @return the string with encoded template parameters names.
        */
    public static String encodeTemplateNames(String s) {
        return TEMPLATE_NAMES_PATTERN.matcher(s).replaceAll("%7B%7D$1");
    }
}

public static String encodeTemplateNames(String s){
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{' || c == '}') {
            sb.append('%');
            sb.append(String.format("%02X", (int) c));
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String encodeTemplateNames(String s) {
    return s.replaceAll("\\{", "%7B").replaceAll("\\}", "%7D");
}

public static String encodeTemplateNames(String s) {
    String encodedString = s.replaceAll("\\{", "%7B").replaceAll("\\}", "%7D");
    return encodedString;
}

