public static String applyRelativePath(String path, String relativePath) {
    // Check if the given path is null
    if (path == null) {
        throw new IllegalArgumentException("Path cannot be null");
    }

    // Check if the given relative path is null
    if (relativePath == null) {
        throw new IllegalArgumentException("Relative path cannot be null");
    }

    // If the relative path is empty, return the given path
    if (relativePath.isEmpty()) {
        return path;
    }

    // Get the file separator
    String fileSeparator = System.getProperty("file.separator");

    // Split the path and relative path into individual components
    String[] pathComponents = path.split(fileSeparator);
    String[] relativePathComponents = relativePath.split(fileSeparator);

    // Get the last component of the path
    String lastPathComponent = pathComponents[pathComponents.length - 1];

    // Get the last component of the relative path
    String lastRelativePathComponent = relativePathComponents[relativePathComponents.length - 1];

    // Check if the last component of the relative path is not equal to the last component of the path
    if (!lastPathComponent.equals(lastRelativePathComponent)) {
        throw new IllegalArgumentException("The last component of the relative path must be equal to the last component of the path");
    }

    // Remove the last component of the relative path
    relativePathComponents = Arrays.copyOf(relativePathComponents, relativePathComponents.length - 1);

    // Join the remaining components of the relative path with the file separator
    String result = String.join(fileSeparator, relativePathComponents);

    // Return the result
    return result;
}

