public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    ThreadSnapshot lastThreadSnapshot = null;

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("HEAP DUMP:")) {
                // Parse the heap dump line
                String[] tokens = line.split(" ");
                long timestamp, threadId;
                try {
                    timestamp = Long.parseLong(tokens[3]);
                    threadId = Long.parseLong(tokens[1]);
                } catch (NumberFormatException e) {
                    throw new IOException("Invalid heap dump line: " + line, e);
                }

                // Add the thread snapshot to the list
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(timestamp, threadId);
                threadSnapshots.add(threadSnapshot);
                lastThreadSnapshot = threadSnapshot;
            } else if (line.startsWith("STACKTRACE:")) {
                // Parse the stack trace line
                String[] tokens = line.split(" ");
                int depth = Integer.parseInt(tokens[1]);
                long[] stackFrameIds = new long[depth];
                for (int i = 0; i < depth; i++) {
                    stackFrameIds[i] = Long.parseLong(tokens[2 + i]);
                }

                // Add the stack trace to the last thread snapshot
                lastThreadSnapshot.addStackTrace(stackFrameIds);
            }
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("#") || line.trim().isEmpty()) {
                continue;
            }
            String[] fields = line.split(",");
            if (fields.length != 7) {
                throw new IOException("Invalid thread snapshot file format");
            }
            String timestamp = fields[0];
            long timeLong = Long.parseLong(timestamp);
            if (!timeRanges.stream().anyMatch(t -> t.contains(timeLong))) {
                continue;
            }
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(
                    UUID.fromString(fields[1]),
                    Thread.State.valueOf(fields[2]),
                    Integer.parseInt(fields[3]),
                    Long.parseLong(fields[4]),
                    Long.parseLong(fields[5]),
                    Integer.parseInt(fields[6])
            );
            threadSnapshots.add(threadSnapshot);
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(
    File file,
    List<ProfileAnalyzeTimeRange> timeRanges
) throws IOException {
    // Parse file into a list of thread snapshots
    List<ThreadSnapshot> threadSnapshots = parseFromFile(file);

    // Filter thread snapshots by time range, if specified
    if (timeRanges != null && !timeRanges.isEmpty()) {
        long startTime = timeRanges.get(0).getStartTime();
        long endTime = timeRanges.get(0).getEndTime();
        threadSnapshots = threadSnapshots.stream()
            .filter(threadSnapshot -> threadSnapshot.getTimestamp() >= startTime && threadSnapshot.getTimestamp() <= endTime)
            .collect(Collectors.toList());
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
	try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
		String line;
		while ((line = reader.readLine()) != null) {
			ThreadSnapshot snapshot = parseThreadSnapshot(line);
			if (isInTimeRange(snapshot, timeRanges)) {
				threadSnapshots.add(snapshot);
			}
		}
	}
	return threadSnapshots;
}

private static boolean isInTimeRange(ThreadSnapshot snapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
	return timeRanges.stream()
			.anyMatch(timeRange -> timeRange.contains(snapshot.getTimestamp()));
}

void parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    ProfileAnalyzeReader reader = new ProfileAnalyzeReader(file);
    while (reader.hasNext()) {
        ProfileAnalyzeRecord record = reader.next();
        long timestamp = record.getTimestamp();
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                threadSnapshots.add(record.getThreadSnapshot());
                break;
            }
        }
    }
    return threadSnapshots;
}
